import knowledge from "../_generated/knowledge.json";
import safety from "../_generated/safety.json";
import { createAskHandler } from "../_lib/handler";
import type { KnowledgePack, PagesContext, SafetyData } from "../_lib/types";

/**
 * Ask the HQ: `GET /api/ask` (status) and `POST /api/ask` (answer as text/event-stream).
 * The knowledge pack and the safety lists are generated by `bun scripts/build-knowledge.ts`
 * (part of `bun run build`) and bundled here, never served as public files.
 * Design and threat model: docs/superpowers/specs/2026-10-11-ask-hq-design.md.
 */
const handler = createAskHandler({ pack: knowledge as unknown as KnowledgePack, safety: safety as SafetyData });

export const onRequest = (context: PagesContext) => handler(context);
